        h->param.rc.psz_stat_in = strdup( h->param.rc.psz_stat_in );

    // 对帧率和时间基数约分
    x264_reduce_fraction( &h->param.i_fps_num, &h->param.i_fps_den );
    x264_reduce_fraction( &h->param.i_timebase_num, &h->param.i_timebase_den );

    /* Init x264_t */
    // 对帧数赋初值
    h->i_frame = -1;
    h->i_frame_num = 0;

